// ===================================================================
// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests for the step engine on the fake site
// Flo: post flow > halt on checkpoint, login, block pages > missing label > pause flag > expect drift
// I/O: real local Chrome (skipped when absent) + mock site > pass or fail (no leaks)
// Run: zig build test -Dfile=ru-flow-runz-test.zig
// ===================================================================
const std = @import("std"); const rigz = @import("te-rigz-brow.zig"); const flow = @import("ru-flow-runz.zig"); const stat = @import("st-stat-main.zig"); const halt = @import("ru-safe-halt.zig"); const conf = @import("cf-conf-load.zig");
const defc: conf.Conf = .{};
fn runOf(rig: *rigz.Rig, store: ?*stat.Stat) flow.Run { return .{ .env = rig.env(), .store = store, .base = rig.base() }; }
fn postSteps(txt: []const u8) [5]flow.Step { return .{ .{ .op = .goto, .text = "/" }, .{ .op = .click, .labs = defc.labl_post_open }, .{ .op = .typez, .labs = defc.labl_post_boxz, .text = txt }, .{ .op = .click, .labs = defc.labl_post_subm, .commit = true }, .{ .op = .expect, .labs = &.{"Hello flow"} } }; }
test "post flow end to end: goto, open, type, submit, expect" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = postSteps("Hello flow"); try flow.runSteps(&run, &stps); try std.testing.expectEqual(@as(u32, 5), run.done); try std.testing.expect(run.crossed); try std.testing.expectEqualStrings("Hello flow", rig.waitRec("post", 3000).?); }
test "checkpoint page stops the flow with Halted and writes nothing" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/checkpoint/1/" }, .{ .op = .click, .labs = defc.labl_post_open } }; try std.testing.expectError(error.Halted, flow.runSteps(&run, &stps)); try std.testing.expectEqual(halt.Halt.checkpoint, run.hltk.?); try std.testing.expectEqual(@as(usize, 0), rig.mock.recCnt()); }
test "login page gives NeedLogin; blocked page gives Unsafe" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const lgn = [_]flow.Step{.{ .op = .goto, .text = "/login/" }}; try std.testing.expectError(error.NeedLogin, flow.runSteps(&run, &lgn)); const blk = [_]flow.Step{.{ .op = .goto, .text = "/blocked" }}; try std.testing.expectError(error.Unsafe, flow.runSteps(&run, &blk)); try std.testing.expectEqual(halt.Halt.blocked, run.hltk.?); }
test "missing label gives NoElement after the retry budget" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); rig.conf.retr_coun_maxz = 2; var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/" }, .{ .op = .click, .labs = &.{"no such button"} } }; try std.testing.expectError(error.NoElement, flow.runSteps(&run, &stps)); }
test "expect times out as Drift" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/" }, .{ .op = .expect, .labs = &.{"never on this page"}, .ms = 600 } }; try std.testing.expectError(error.Drift, flow.runSteps(&run, &stps)); }
test "pause flag stops the flow before any step" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var pth: [128]u8 = undefined; const dbp = try std.mem.printSentinel(&pth, ".zig-cache/tmp/{s}/fb.db", .{rig.tmpz.sub_path}, 0); var sto = try stat.Stat.open(std.testing.allocator, dbp); defer sto.close(); try sto.flagSet("pause", true); var run = runOf(&rig, &sto); const stps = [_]flow.Step{.{ .op = .goto, .text = "/" }}; try std.testing.expectError(error.Paused, flow.runSteps(&run, &stps)); try std.testing.expectEqual(@as(u32, 0), run.done); try sto.flagSet("pause", false); try flow.runSteps(&run, &stps); try std.testing.expectEqual(@as(u32, 1), run.done); }
test "a known popup is dismissed after page load, then the page works" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/popup/" }, .{ .op = .click, .labs = &.{"Do thing"} } }; try flow.runSteps(&run, &stps); try std.testing.expect(rig.waitPre("popup|closed", 3000)); try std.testing.expect(rig.waitPre("btn|Do thing|", 3000)); }
test "an unknown dialog on load halts for the owner (overlay, needs you)" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/cookie" }, .{ .op = .click, .labs = &.{"x"} } }; try std.testing.expectError(error.Halted, flow.runSteps(&run, &stps)); try std.testing.expectEqual(halt.Halt.overlay, run.hltk.?); try std.testing.expectEqual(halt.Class.needs, halt.classOf(run.hltk.?)); }
test "a rate-limit dialog is UNSAFE, the same words in page text are not" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{.{ .op = .goto, .text = "/ratelimit" }}; try std.testing.expectError(error.Unsafe, flow.runSteps(&run, &stps)); try std.testing.expectEqual(halt.Class.unsafe, halt.classOf(run.hltk.?)); }
test "toggle reaches the wanted state once and does nothing when already there" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const on = [_]flow.Step{ .{ .op = .goto, .text = "/toggle/" }, .{ .op = .toggle, .labs = &.{"Notifications"}, .text = "on" } }; try flow.runSteps(&run, &on); try std.testing.expect(rig.waitPre("tog|Notifications=on", 3000)); const again = [_]flow.Step{.{ .op = .toggle, .labs = &.{"Notifications"}, .text = "on" }}; try flow.runSteps(&run, &again); try std.testing.expectEqual(@as(usize, 1), rig.mock.recNum("tog")); const off = [_]flow.Step{.{ .op = .toggle, .labs = &.{"Notifications"}, .text = "off" }}; try flow.runSteps(&run, &off); try std.testing.expect(rig.waitPre("tog|Notifications=off", 3000)); }
test "select picks an option from a combobox; hover then click works" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); const stps = [_]flow.Step{ .{ .op = .goto, .text = "/marketplace/create/wizard" }, .{ .op = .select, .role = "combobox", .labs = &.{"Category"}, .text = "Bikes" }, .{ .op = .select, .role = "combobox", .labs = &.{"Condition"}, .text = "Used" } }; try flow.runSteps(&run, &stps); try std.testing.expect(rig.waitPre("opt|Category=Bikes", 3000)); try std.testing.expect(rig.waitPre("opt|Condition=Used", 3000)); const hov = [_]flow.Step{ .{ .op = .goto, .text = "/posts/1" }, .{ .op = .hover, .labs = &.{"React"} }, .{ .op = .click, .role = "menuitem", .labs = &.{"Love"} } }; try flow.runSteps(&run, &hov); try std.testing.expect(rig.waitPre("hov|React>Love", 3000)); }
test "cool pace doubles the gaps but still completes" { var rig: rigz.Rig = undefined; try rig.up(); defer rig.down(); var run = runOf(&rig, null); run.cool = true; const stps = [_]flow.Step{ .{ .op = .goto, .text = "/" }, .{ .op = .click, .labs = rig.conf.labl_post_open } }; try flow.runSteps(&run, &stps); try std.testing.expectEqual(@as(u32, 2), run.done); }
